import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const STATUS_TEXT: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_CLASS: Record<UserStatus, string> = {
  active: 'jx-badge jx-badge--success',
  disabled: 'jx-badge jx-badge--muted',
};

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const start = (currentPage - 1) * PAGE_SIZE;

  const rows = useMemo(
    () => users.slice(start, start + PAGE_SIZE),
    [users, start],
  );

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      <table className="jx-table">
        <thead className="jx-table__head">
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody className="jx-table__body">
          {rows.map((user) => (
            <tr key={user.id} className="jx-table__row">
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <span className={STATUS_CLASS[user.status]}>
                  {STATUS_TEXT[user.status]}
                </span>
              </td>
            </tr>
          ))}
          {rows.length === 0 && (
            <tr className="jx-table__row">
              <td colSpan={3} className="jx-text--muted">
                Пользователей нет
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <nav
        className="jx-cluster"
        aria-label="Постраничная навигация"
        style={{
          gap: 'var(--jx-space-3)',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <Button
          variant="secondary"
          disabled={currentPage <= 1}
          onClick={() => setPage(currentPage - 1)}
        >
          Назад
        </Button>
        <span className="jx-text--muted" aria-live="polite">
          Страница {currentPage} из {pageCount}
        </span>
        <Button
          variant="secondary"
          disabled={currentPage >= pageCount}
          onClick={() => setPage(currentPage + 1)}
        >
          Вперёд
        </Button>
      </nav>
    </div>
  );
}

